use crate::dag::{ArithmeticOp, ComparisonOp, LogicalOp, OperatorKind};
use crate::tokenize::TokenKind;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BinaryOpLevel {
    Or,
    And,
    Comparison,
    Additive,
    Multiplicative,
}

/// Token-to-`OperatorKind` map for the parser's per-precedence-level
/// functions. Authored as `binary_op_*: BinaryOpRow` rows in
/// `src/v3/compiler/parse_tables.dag`; regenerated by `regen_parse_tables`.
pub fn binary_op_at_level(tk: &TokenKind, level: BinaryOpLevel) -> Option<OperatorKind> {
    match (tk, level) {
        (TokenKind::AmpAmp, BinaryOpLevel::And) => Some(OperatorKind::Logical(LogicalOp::And)),
        (TokenKind::EqEq, BinaryOpLevel::Comparison) => {
            Some(OperatorKind::Comparison(ComparisonOp::Eq))
        }
        (TokenKind::Ge, BinaryOpLevel::Comparison) => {
            Some(OperatorKind::Comparison(ComparisonOp::Ge))
        }
        (TokenKind::Gt, BinaryOpLevel::Comparison) => {
            Some(OperatorKind::Comparison(ComparisonOp::Gt))
        }
        (TokenKind::Le, BinaryOpLevel::Comparison) => {
            Some(OperatorKind::Comparison(ComparisonOp::Le))
        }
        (TokenKind::Lt, BinaryOpLevel::Comparison) => {
            Some(OperatorKind::Comparison(ComparisonOp::Lt))
        }
        (TokenKind::Minus, BinaryOpLevel::Additive) => {
            Some(OperatorKind::Arithmetic(ArithmeticOp::Sub))
        }
        (TokenKind::NotEq, BinaryOpLevel::Comparison) => {
            Some(OperatorKind::Comparison(ComparisonOp::Ne))
        }
        (TokenKind::PipePipe, BinaryOpLevel::Or) => Some(OperatorKind::Logical(LogicalOp::Or)),
        (TokenKind::Plus, BinaryOpLevel::Additive) => {
            Some(OperatorKind::Arithmetic(ArithmeticOp::Add))
        }
        (TokenKind::Slash, BinaryOpLevel::Multiplicative) => {
            Some(OperatorKind::Arithmetic(ArithmeticOp::Div))
        }
        (TokenKind::Star, BinaryOpLevel::Multiplicative) => {
            Some(OperatorKind::Arithmetic(ArithmeticOp::Mul))
        }
        _ => None,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ItemDispatchKind {
    Data,
    Fn,
    Import,
    Let,
    Module,
    Type,
}

/// Top-level item keyword (`parse_item`) → dispatch class.
/// `ItemDispatchKind` is emitted from unique `Kw`-stripped labels of
/// `TopLevelItemKwRow { token_variant }` rows — not authored as a substrate coproduct.
pub fn top_level_item_dispatch(kind: &TokenKind) -> Option<ItemDispatchKind> {
    match kind {
        TokenKind::KwData => Some(ItemDispatchKind::Data),
        TokenKind::KwFn => Some(ItemDispatchKind::Fn),
        TokenKind::KwImport => Some(ItemDispatchKind::Import),
        TokenKind::KwLet => Some(ItemDispatchKind::Let),
        TokenKind::KwModule => Some(ItemDispatchKind::Module),
        TokenKind::KwType => Some(ItemDispatchKind::Type),
        _ => None,
    }
}

/// Keyword membership table for top-level type-RHS boundary lookahead.
/// Projected from the existing `TopLevelItemKwRow` rows in
/// `src/v3/compiler/parse_tables.dag`.
pub fn is_type_rhs_boundary_keyword(kind: &TokenKind) -> bool {
    matches!(
        kind,
        TokenKind::KwData
            | TokenKind::KwFn
            | TokenKind::KwImport
            | TokenKind::KwLet
            | TokenKind::KwModule
            | TokenKind::KwType
    )
}
